package com.fifotech.task.service;
import com.fifotech.task.domain.*;import com.fifotech.task.dto.ApiDtos.DashboardResponse;import com.fifotech.task.repository.*;import org.springframework.stereotype.Service;
@Service public class DashboardService {private final UserRepository users;private final TaskRepository tasks;public DashboardService(UserRepository users,TaskRepository tasks){this.users=users;this.tasks=tasks;}public DashboardResponse stats(User u){Long employee=u.getRole()==Role.EMPLOYEE?u.getId():null;Long manager=u.getRole()==Role.MANAGER?u.getId():null;return new DashboardResponse(u.getRole()==Role.ADMIN?users.count():0,tasks.countScope(employee,manager),tasks.countByScope(TaskStatus.DONE,employee,manager),u.getRole()==Role.MANAGER?users.countByManagerIdAndActiveTrue(u.getId()):0,tasks.countByScope(TaskStatus.PENDING,employee,manager),tasks.countByScope(TaskStatus.IN_PROGRESS,employee,manager),tasks.countByScope(TaskStatus.DONE,employee,manager));}}
